const $f=(s,r=document)=>r.querySelector(s);
const $$f=(s,r=document)=>[...r.querySelectorAll(s)];
const ef=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const API_FINAL='/api/observatorio-politico';
const cacheHistorico=new Map();

