 ['OpenAlex · PDFs e produção acadêmica aberta','https://openalex.org/'],['Project Gutenberg','https://www.gutenberg.org/'],['Open Library','https://openlibrary.org/'],['Google Books','https://books.google.com/'],['Wikisource','https://pt.wikisource.org/'],['Internet Archive','https://archive.org/'],['Europe PMC','https://europepmc.org/'],['ERIC · Educação','https://eric.ed.gov/'],['DOAJ','https://doaj.org/'],['Wikibooks','https://pt.wikibooks.org/'],['Wikiversidade','https://pt.wikiversity.org/'],['OAPEN','https://library.oapen.org/'],['DOAB','https://directory.doabooks.org/'],['SciELO Livros','https://books.scielo.org/'],['NCBI Bookshelf','https://www.ncbi.nlm.nih.gov/books/'],['arXiv','https://arxiv.org/'],['Library of Congress','https://www.loc.gov/'],['Gallica · BnF','https://gallica.bnf.fr/'],['Biblioteca Nacional Digital','https://bndigital.bn.gov.br/'],['DPLA','https://dp.la/'],['Crossref','https://www.crossref.org/'],['CORE','https://core.ac.uk/'],['Semantic Scholar','https://www.semanticscholar.org/'],['Europeana','https://www.europeana.eu/'],['DigitalNZ','https://digitalnz.org/'],['Trove','https://trove.nla.gov.au/'],['Open Textbook Library','https://open.umn.edu/opentextbooks/'],['OpenStax','https://openstax.org/'],['Pressbooks Directory','https://pressbooks.directory/'],['Zenodo','https://zenodo.org/'],['HAL','https://hal.science/'],['OpenAIRE','https://explore.openaire.eu/'],['DataCite','https://datacite.org/'],['Wikidata','https://www.wikidata.org/']
