 ['Etnolinguística / Curt Nimuendajú','https://www.etnolinguistica.org/'],['Bloom Library','https://bloomlibrary.org/'],['Museu Nacional dos Povos Indígenas','https://pesquisa.museudoindio.gov.br/'],['Instituto Socioambiental · ISA','https://pib.socioambiental.org/'],['AILLA','https://ailla.utexas.org/'],['OLAC','https://www.language-archives.org/'],['BDTD / IBICT','https://bdtd.ibict.br/'],['Tatoeba','https://tatoeba.org/'],['PanLex','https://panlex.org/'],['Wiktionary / Wikcionário','https://www.wiktionary.org/'],['Lingua Libre','https://lingualibre.org/'],['MERLOT','https://www.merlot.org/'],['LibreTexts','https://libretexts.org/'],['ELAR','https://www.elararchive.org/'],['The Language Archive','https://archive.mpi.nl/'],['Kaipuleohone','https://scholarspace.manoa.hawaii.edu/handle/10125/4250'],['CoRSAL','https://corsal.unt.edu/'],['COERLL','https://coerll.utexas.edu/'],['OER Commons','https://www.oercommons.org/'],['Live Lingua / Peace Corps','https://www.livelingua.com/'],['Mozilla Common Voice','https://commonvoice.mozilla.org/datasets']
