 ['OpenStax · Matemática','https://openstax.org/subjects/math'],['Open Textbook Library · Mathematics','https://open.umn.edu/opentextbooks/subjects/mathematics'],['Pressbooks Directory','https://pressbooks.directory/'],['OpenAlex · camada acadêmica','https://openalex.org/'],['Acervo curado da Biblioteca Livre','https://openstax.org/subjects/math']
